import * as helpers from "./constants/helpers";
export default {
  data() {
    return {
      availableLinks: [],
    }
  },
  watch: {
    '$route.params': {
      handler(newValue) {
        this.availableLinks = helpers.getConstantsMenu('header_third', newValue.slug);
      },
      immediate: true,
    }
  },
  created: function() {
    this.availableLinks = helpers.getConstantsMenu('header_third', this.$route.params.slug);
  }
}
